package com.citacloud.app.views;

import com.citacloud.app.models.*; import com.citacloud.app.security.*; import com.citacloud.app.services.*; import com.citacloud.app.views.components.PaginadorTabla;
import com.vaadin.flow.component.Component; import com.vaadin.flow.component.button.*; import com.vaadin.flow.component.combobox.ComboBox; import com.vaadin.flow.component.datepicker.DatePicker; import com.vaadin.flow.component.dialog.Dialog; import com.vaadin.flow.component.formlayout.FormLayout; import com.vaadin.flow.component.grid.Grid; import com.vaadin.flow.component.html.*; import com.vaadin.flow.component.icon.VaadinIcon; import com.vaadin.flow.component.notification.Notification; import com.vaadin.flow.component.orderedlayout.*; import com.vaadin.flow.component.textfield.BigDecimalField; import com.vaadin.flow.component.textfield.TextField; import com.vaadin.flow.data.value.ValueChangeMode; import com.vaadin.flow.router.*; import jakarta.annotation.security.PermitAll; import java.math.*; import java.time.*; import java.time.format.DateTimeFormatter; import java.text.NumberFormat; import java.util.*;

@Route(value="cuentas-por-cobrar",layout=MainLayout.class) @PageTitle("Cuentas por cobrar | CitaCloud") @PermitAll
public class CuentasPorCobrarView extends VerticalLayout {
 private static final DateTimeFormatter FECHA=DateTimeFormatter.ofPattern("dd/MM/yyyy"),FECHA_HORA=DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm"); private final FacturacionService facturacion; private final PagoService pagos; private final UUID empresa; private final Grid<Factura> tabla=new Grid<>(Factura.class,false); private final PaginadorTabla<Factura> paginador=new PaginadorTabla<>(tabla); private final TextField buscar=new TextField(); private final ComboBox<String> estado=new ComboBox<>(); private final DatePicker desde=new DatePicker("Desde"),hasta=new DatePicker("Hasta"); private final Div indicadores=new Div(),vacio=new Div();
 public CuentasPorCobrarView(FacturacionService f,PagoService p){facturacion=f;pagos=p;TenantUserDetails u=AuthService.getAuthenticatedUser();empresa=u==null?null:u.getEmpresaId();setWidthFull();setPadding(true);setSpacing(true);paginador.setFilasPorPagina(20);cabecera();filtros();tabla();cargar();}
 private void cabecera(){H2 t=new H2("CUENTAS POR COBRAR");t.getStyle().set("margin","0");add(t,new Paragraph("Control y seguimiento de los saldos pendientes generados por facturación."));indicadores.setWidthFull();indicadores.getStyle().set("display","flex").set("gap","1rem").set("flex-wrap","wrap");add(indicadores);}
 private void filtros(){buscar.setPlaceholder("Paciente, factura o historia clínica");buscar.setClearButtonVisible(true);buscar.setWidth("min(100%,360px)");buscar.setValueChangeMode(ValueChangeMode.LAZY);buscar.setValueChangeTimeout(350);buscar.addValueChangeListener(e->cargar());estado.setItems("Todas","Pendientes","Por vencer","Vencidas","Pagadas");estado.setValue("Pendientes");estado.setLabel("Estado");estado.addValueChangeListener(e->cargar());desde.addValueChangeListener(e->cargar());hasta.addValueChangeListener(e->cargar());Button limpiar=new Button(VaadinIcon.ERASER.create(),e->{buscar.clear();estado.setValue("Pendientes");desde.clear();hasta.clear();});limpiar.setTooltipText("Limpiar");limpiar.getStyle().set("background-color","#ffffff").set("color","#1e293b");limpiar.addThemeVariants(ButtonVariant.LUMO_TERTIARY);HorizontalLayout l=new HorizontalLayout(buscar,desde,hasta,estado,limpiar);l.setWidthFull();l.setAlignItems(Alignment.END);l.getStyle().set("flex-wrap","wrap");add(l);}
 private void tabla(){tabla.addColumn(Factura::getNumero).setHeader("FACTURA").setAutoWidth(true);tabla.addColumn(f->f.getPaciente()==null?"—":f.getPaciente().getNombreCompleto()).setHeader("PACIENTE").setFlexGrow(1);tabla.addColumn(f->fecha(f.getFecha())).setHeader("EMISIÓN");tabla.addColumn(f->dinero(f.getTotal())).setHeader("TOTAL");tabla.addColumn(f->dinero(f.getMontoPagado())).setHeader("PAGADO");tabla.addColumn(f->dinero(f.getSaldo())).setHeader("PENDIENTE");tabla.addColumn(f->ultimoPago(f).map(p->fecha(p.getFecha())).orElse("—")).setHeader("FECHA DE PAGO");tabla.addColumn(this::estadoVisual).setHeader("ESTADO");tabla.addComponentColumn(f->{Button ver=new Button(VaadinIcon.EYE.create(),e->detalle(f));ver.setTooltipText("Ver detalle");Button pagar=new Button(VaadinIcon.CREDIT_CARD.create(),e->registrarPago(f));pagar.setTooltipText("Registrar pago");pagar.setEnabled(esPagable(f));return new HorizontalLayout(ver,pagar);}).setHeader("ACCIONES");tabla.setWidthFull();tabla.setAllRowsVisible(true);tabla.getStyle().set("flex","0 0 auto");add(tabla,paginador,vacio);}
 private boolean esPagable(Factura f){String e=estadoVisual(f);return "PENDIENTE".equals(e)||"PARCIAL".equals(e);}
 private void cargar(){if(empresa==null){paginador.setItems(List.of());return;}List<Factura> todas=facturacion.listar(empresa);List<Factura> ultimas=todas.stream().limit(25).toList();LocalDate hoy=LocalDate.now();paginador.setItems(ultimas.stream().filter(f->coincide(f,buscar.getValue(),desde.getValue(),hasta.getValue(),estado.getValue(),hoy)).toList());actualizarIndicadores(todas,hoy);vacio.removeAll();if(paginador==null)return;}
 private boolean coincide(Factura f,String q,LocalDate d,LocalDate h,String filtro,LocalDate hoy){if(f.getFecha()!=null&&((d!=null&&f.getFecha().isBefore(d))||(h!=null&&f.getFecha().isAfter(h))))return false;String x=q==null?"":q.trim().toLowerCase(Locale.ROOT);if(!x.isBlank()&&!((f.getNumero()!=null&&f.getNumero().toLowerCase(Locale.ROOT).contains(x))||(f.getPaciente()!=null&&((f.getPaciente().getNombreCompleto()!=null&&f.getPaciente().getNombreCompleto().toLowerCase(Locale.ROOT).contains(x))||(f.getPaciente().getNumeroExpediente()!=null&&f.getPaciente().getNumeroExpediente().toLowerCase(Locale.ROOT).contains(x))))))return false;return switch(filtro==null?"Pendientes":filtro){case "Todas"->true;case "Pagadas"->f.getSaldo()==null||f.getSaldo().signum()==0;case "Vencidas"->f.getSaldo()!=null&&f.getSaldo().signum()>0&&f.getFecha()!=null&&f.getFecha().plusDays(30).isBefore(hoy);case "Por vencer"->f.getSaldo()!=null&&f.getSaldo().signum()>0&&f.getFecha()!=null&&!f.getFecha().plusDays(30).isBefore(hoy);default->f.getSaldo()!=null&&f.getSaldo().signum()>0;};}
 private void actualizarIndicadores(List<Factura> t,LocalDate h){List<Factura> p=t.stream().filter(f->f.getSaldo()!=null&&f.getSaldo().signum()>0).toList(),v=p.stream().filter(f->f.getFecha()!=null&&f.getFecha().plusDays(30).isBefore(h)).toList(),pv=p.stream().filter(f->!v.contains(f)).toList();BigDecimal mes=pagos.listar(empresa).stream().filter(x->x.getFecha()!=null&&x.getFecha().getMonth()==h.getMonth()&&x.getFecha().getYear()==h.getYear()&&!"VOIDED".equals(x.getEstado())).map(Pago::getMonto).reduce(BigDecimal.ZERO,BigDecimal::add);indicadores.removeAll();indicadores.add(tarjeta("TOTAL PENDIENTE",dinero(p.stream().map(Factura::getSaldo).reduce(BigDecimal.ZERO,BigDecimal::add))+" · "+p.size()+" cuentas"),tarjeta("POR VENCER",dinero(pv.stream().map(Factura::getSaldo).reduce(BigDecimal.ZERO,BigDecimal::add))+" · "+pv.size()+" cuentas"),tarjeta("VENCIDO",dinero(v.stream().map(Factura::getSaldo).reduce(BigDecimal.ZERO,BigDecimal::add))+" · "+v.size()+" cuentas"),tarjeta("COBRADO ESTE MES",dinero(mes)));}
 private void detalle(Factura f){Dialog d=new Dialog();d.setWidth("min(680px,96vw)");d.setHeaderTitle("Detalle de cuenta · "+f.getNumero());FormLayout datos=new FormLayout();datos.setResponsiveSteps(new FormLayout.ResponsiveStep("0",2));datos.addFormItem(new Span(f.getPaciente()==null?"—":f.getPaciente().getNombreCompleto()),"Paciente");datos.addFormItem(new Span(f.getPaciente()==null?"—":f.getPaciente().getNumeroExpediente()),"Historia clínica");datos.addFormItem(new Span(dinero(f.getTotal())),"Total factura");datos.addFormItem(new Span(dinero(f.getMontoPagado())),"Pagado");datos.addFormItem(new Span(fecha(f.getFecha())),"Emisión");datos.addFormItem(new Span(ultimoPago(f).map(p->fecha(p.getFecha())).orElse("—")),"Fecha de pago");VerticalLayout c=new VerticalLayout(datos,new H2("Saldo pendiente: "+dinero(f.getSaldo())),new H4("Historial de pagos"));pagosFactura(f).forEach(p->{Span info=new Span(codigo(p)+" · "+(p.getCreadoEn()==null?fecha(p.getFecha()):p.getCreadoEn().format(FECHA_HORA))+" · "+p.getMetodoPago()+" · "+dinero(p.getMonto())+" · "+(p.getEstado()==null?"APLICADO":p.getEstado()));Button verPago=new Button(VaadinIcon.PRINT.create(),e->getUI().ifPresent(ui->ui.getPage().open("/pagos/"+p.getId()+"/recibo","_blank")));verPago.setTooltipText("Ver recibo");verPago.addThemeVariants(ButtonVariant.LUMO_PRIMARY);c.add(new HorizontalLayout(info,verPago));});Button cancelar=new Button(VaadinIcon.CLOSE.create(),e->d.close());cancelar.setTooltipText("Cancelar");cancelar.getStyle().set("background-color","#ffffff").set("color","#1e293b");cancelar.addThemeVariants(ButtonVariant.LUMO_TERTIARY);HorizontalLayout acciones=new HorizontalLayout(cancelar);acciones.setWidthFull();acciones.setJustifyContentMode(JustifyContentMode.END);d.add(c);d.getFooter().add(acciones);d.open();}
 private void verRecibo(Factura f){ultimoPago(f).ifPresentOrElse(p->getUI().ifPresent(ui->ui.getPage().open("/pagos/"+p.getId()+"/recibo","_blank")),()->Notification.show("No existe un recibo asociado a esta factura."));}
 private void registrarPago(Factura f){Dialog d=new Dialog();d.setHeaderTitle("Registrar pago · "+f.getNumero());BigDecimalField monto=new BigDecimalField("Monto a pagar *");monto.setLocale(Locale.US);monto.setPrefixComponent(new Span("RD$"));monto.setValue(f.getSaldo());ComboBox<String> metodo=new ComboBox<>("Método de pago *",List.of("EFECTIVO","TARJETA","TRANSFERENCIA","CHEQUE","OTRO"));metodo.setValue("EFECTIVO");TextField referencia=new TextField("Referencia / autorización");Button confirmar=new Button(VaadinIcon.DISC.create(),e->{try{BigDecimal valor=monto.getValue();CargoFinanciero cargo=pagos.pendientes(empresa,f.getPaciente().getId()).stream().filter(x->x.getFactura()!=null&&x.getFactura().getId().equals(f.getId())).findFirst().orElseThrow(()->new IllegalArgumentException("No existe saldo aplicable para esta factura."));UUID sucursalId=cargo.getSucursal()==null?null:cargo.getSucursal().getId();Pago p=pagos.registrar(empresa,new PagoService.Solicitud(f.getPaciente().getId(),sucursalId,metodo.getValue(),valor,"EFECTIVO".equals(metodo.getValue())?valor:null,referencia.getValue(),null,null,UUID.randomUUID().toString(),List.of(new PagoService.Aplicacion(cargo.getId(),valor))));d.close();cargar();Notification.show("Pago registrado correctamente.");getUI().ifPresent(ui->ui.getPage().open("/pagos/"+p.getId()+"/recibo","_blank"));}catch(Exception x){Notification.show(x.getMessage(),5000,Notification.Position.MIDDLE);}});confirmar.setTooltipText("Registrar pago");confirmar.addThemeVariants(ButtonVariant.LUMO_SUCCESS);confirmar.getStyle().set("background-color","#16a34a").set("color","#ffffff");Button cancelar=new Button(VaadinIcon.CLOSE.create(),e->d.close());cancelar.setTooltipText("Cancelar");cancelar.getStyle().set("background-color","#ffffff").set("color","#1e293b");cancelar.addThemeVariants(ButtonVariant.LUMO_TERTIARY);d.add(new FormLayout(new Span("Paciente: "+(f.getPaciente()==null?"—":f.getPaciente().getNombreCompleto())),new Span("Factura: "+f.getNumero()),new Span("Saldo pendiente: "+dinero(f.getSaldo())),monto,metodo,referencia));HorizontalLayout acciones=new HorizontalLayout(confirmar,cancelar);acciones.setWidthFull();acciones.setJustifyContentMode(JustifyContentMode.END);d.getFooter().add(acciones);d.open();}
 private List<Pago> pagosFactura(Factura f){return pagos.listar(empresa).stream().filter(p->{if(p.getFactura()!=null&&p.getFactura().getId().equals(f.getId()))return true;return pagos.aplicaciones(empresa,p.getId()).stream().anyMatch(a->a.getCargo()!=null&&a.getCargo().getFactura()!=null&&a.getCargo().getFactura().getId().equals(f.getId()));}).toList();} private Optional<Pago> ultimoPago(Factura f){return pagosFactura(f).stream().max(Comparator.comparing(Pago::getFecha,Comparator.nullsFirst(Comparator.naturalOrder())).thenComparing(Pago::getCreadoEn,Comparator.nullsFirst(Comparator.naturalOrder())));} private Component tarjeta(String t,String v){Div d=new Div(new Span(t),new H3(v));d.getStyle().set("flex","1 1 220px").set("padding",".75rem 1rem").set("background","var(--lumo-contrast-5pct)").set("border-radius","var(--lumo-border-radius-l)");return d;} private String estadoVisual(Factura f){if(f.getSaldo()==null||f.getSaldo().signum()==0)return "PAGADA";return f.getFecha()!=null&&f.getFecha().plusDays(30).isBefore(LocalDate.now())?"VENCIDA":(f.getMontoPagado()!=null&&f.getMontoPagado().signum()>0?"PARCIAL":"PENDIENTE");} private String fecha(LocalDate v){return v==null?"—":v.format(FECHA);} private String dinero(BigDecimal v){NumberFormat n=NumberFormat.getNumberInstance(Locale.US);n.setMinimumFractionDigits(2);n.setMaximumFractionDigits(2);return "RD$ "+n.format(v==null?BigDecimal.ZERO:v);} private String codigo(Pago p){return p.getNumero()==null?"PAG-"+p.getId().toString().substring(0,8).toUpperCase(Locale.ROOT):p.getNumero();}
}
